import json
from pathlib import Path


questions = []


def q(topic, difficulty, question, options, answer, explanation):
    questions.append({
        "id": len(questions) + 1,
        "language": "SQL",
        "difficulty": difficulty,
        "topic": topic,
        "companyPattern": ["TCS", "Infosys", "Wipro", "Cognizant"],
        "question": question,
        "options": options,
        "answer": answer,
        "explanation": explanation,
    })


# SQL fundamentals (1-10)
q("SQL Fundamentals", "Easy", "What does SQL stand for?", ["Structured Query Language", "Simple Question Language", "System Query Logic", "Sequential Query Language"], 0, "SQL stands for Structured Query Language, the standard language used to define, query, and manipulate relational data.")
q("SQL Fundamentals", "Easy", "What is the primary purpose of a DBMS?", ["To design web pages", "To store, organize, and manage data", "To compile source code", "To route network packets"], 1, "A database management system provides facilities for storing, querying, updating, securing, and managing data.")
q("SQL Fundamentals", "Easy", "How is data primarily organized in a relational database?", ["As objects only", "As unstructured files", "As tables made of rows and columns", "As network frames"], 2, "A relational database represents relations as tables, with rows representing records and columns representing attributes.")
q("SQL Fundamentals", "Easy", "In a relational table, what is a row commonly called?", ["Attribute", "Tuple", "Domain", "Schema"], 1, "A row in a relational relation is called a tuple; it represents one record or instance.")
q("SQL Fundamentals", "Easy", "In a relational table, what is a column commonly called?", ["Attribute", "Tuple", "Transaction", "Cursor"], 0, "A column describes an attribute of the relation, such as salary or department_id.")
q("SQL Fundamentals", "Easy", "What does a database schema describe?", ["Only the current row values", "The network route to a database", "The structure of database objects and relationships", "The password for every user"], 2, "A schema describes structures such as tables, columns, constraints, views, and relationships.")
q("SQL Fundamentals", "Easy", "SQL is generally described as which type of language?", ["Procedural", "Declarative", "Assembly", "Markup"], 1, "SQL is declarative: the user specifies the desired result, while the database optimizer chooses an execution strategy.")
q("SQL Fundamentals", "Easy", "Which SQL command is used to retrieve data?", ["FETCHONLY", "GET", "READ", "SELECT"], 3, "SELECT retrieves rows and columns from one or more tables or other queryable sources.")
q("SQL Fundamentals", "Easy", "Which character commonly terminates a SQL statement?", ["Colon (:)", "Comma (,)", "Semicolon (;)", "Hash (#)"], 2, "A semicolon is the conventional SQL statement terminator in clients and scripts.")
q("SQL Fundamentals", "Medium", "What is true about duplicate rows in a table without a uniqueness constraint?", ["They can exist", "They are always rejected", "They are automatically merged", "They are converted to NULL"], 0, "Relational tables may contain duplicate rows unless a primary key, unique constraint, or other rule prevents them.")

# DDL, DML, DCL, and TCL (11-20)
q("SQL Command Categories", "Easy", "Which category does CREATE TABLE belong to?", ["DDL", "DML", "DCL", "TCL"], 0, "CREATE TABLE defines a database object, so it is a Data Definition Language command.")
q("SQL Command Categories", "Easy", "Which category does ALTER TABLE belong to?", ["DML", "TCL", "DDL", "DCL"], 2, "ALTER TABLE changes the definition of a table, making it a DDL command.")
q("SQL Command Categories", "Easy", "What does DROP TABLE generally do?", ["Deletes only duplicate rows", "Removes the table definition and its data", "Removes one column value", "Commits the current transaction"], 1, "DROP TABLE removes the table object, including its definition and normally its stored rows.")
q("SQL Command Categories", "Easy", "What is the typical effect of TRUNCATE TABLE?", ["It deletes selected rows using a WHERE clause", "It renames the table", "It removes one column", "It removes all rows without a WHERE clause"], 3, "TRUNCATE is intended to remove all rows from a table efficiently; it does not support a row filter in standard usage.")
q("SQL Command Categories", "Easy", "Which category does INSERT belong to?", ["DML", "DDL", "DCL", "TCL"], 0, "INSERT changes table data, so it is a Data Manipulation Language command.")
q("SQL Command Categories", "Easy", "Which category does UPDATE belong to?", ["DCL", "DML", "DDL", "TCL"], 1, "UPDATE modifies existing table rows and is therefore a DML command.")
q("SQL Command Categories", "Easy", "Which category does DELETE belong to?", ["TCL", "DCL", "DML", "DDL"], 2, "DELETE removes rows from a table and belongs to DML.")
q("SQL Command Categories", "Easy", "Which command grants privileges to a database user or role?", ["ALLOW", "PERMIT", "GRANT", "AUTHORIZE"], 2, "GRANT gives specified privileges on database objects to users or roles.")
q("SQL Command Categories", "Easy", "Which command removes previously granted privileges?", ["REMOVE ACCESS", "REVOKE", "DENY", "CANCEL"], 1, "REVOKE withdraws privileges that were previously granted to a user or role.")
q("SQL Command Categories", "Easy", "Which command makes the current transaction changes permanent?", ["COMMIT", "SAVE", "APPLY", "PUBLISH"], 0, "COMMIT ends the transaction and makes its changes durable according to the database system's rules.")

# SELECT and filtering (21-30)
q("SELECT and Filtering", "Easy", "What is the purpose of a WHERE clause?", ["To rename a table", "To filter rows that satisfy a condition", "To create an index", "To group result columns"], 1, "WHERE evaluates a predicate for rows and keeps only rows for which the predicate is true.")
q("SELECT and Filtering", "Easy", "Which clause sorts query results?", ["GROUP BY", "SORT BY", "ORDER BY", "ARRANGE"], 2, "ORDER BY sorts the final result according to one or more expressions.")
q("SELECT and Filtering", "Easy", "What is the default direction of ORDER BY in standard SQL?", ["Ascending", "Descending", "Random", "Database-dependent only"], 0, "ASC is the default ordering direction when neither ASC nor DESC is specified.")
q("SELECT and Filtering", "Easy", "Which clause can limit the number of rows returned in systems that support it?", ["CAP", "TOPONLY", "LIMIT", "RESTRICT ROWS"], 2, "LIMIT is widely supported for restricting the number of rows returned, although some systems use TOP or FETCH syntax.")
q("SELECT and Filtering", "Easy", "What does SELECT DISTINCT do?", ["Sorts rows alphabetically", "Removes duplicate rows from the selected result", "Deletes duplicate table rows", "Selects only NULL values"], 1, "DISTINCT eliminates duplicate combinations of the selected expressions in the result.")
q("SELECT and Filtering", "Easy", "What is the main purpose of a column alias?", ["To give a result expression a readable temporary name", "To create a permanent column", "To encrypt a column", "To add an index"], 0, "An alias labels a selected expression or table for readability and can simplify references in a query.")
q("SELECT and Filtering", "Easy", "Are the endpoints included when BETWEEN is used?", ["Neither endpoint is included", "Only the lower endpoint is included", "Both endpoints are included", "Only the upper endpoint is included"], 2, "BETWEEN is inclusive, so BETWEEN 10 AND 20 includes 10 and 20.")
q("SELECT and Filtering", "Easy", "What does the IN predicate test?", ["Whether a value matches one of a listed set of values", "Whether a table has an index", "Whether a transaction is active", "Whether a column is numeric"], 0, "IN returns true when the expression equals at least one value in the supplied list or subquery result.")
q("SELECT and Filtering", "Easy", "In a LIKE pattern, what does the percent sign (%) represent?", ["Exactly one character", "A digit only", "A space", "Any sequence of zero or more characters"], 3, "The percent wildcard matches any sequence of characters, including an empty sequence.")
q("SELECT and Filtering", "Medium", "What is the purpose of the ESCAPE clause with LIKE?", ["To define a character that quotes a wildcard", "To stop a transaction", "To ignore NULLs", "To sort case-insensitively"], 0, "ESCAPE lets a query specify a character that makes a wildcard such as % or _ literal in a pattern.")

# NULLs and expressions (31-40)
q("NULLs and Expressions", "Easy", "What does NULL generally represent in SQL?", ["Zero", "An unknown, missing, or inapplicable value", "An empty string in every database", "False"], 1, "NULL represents the absence of a known value; it is not the same as zero, an empty string, or false.")
q("NULLs and Expressions", "Easy", "Which predicate correctly tests whether a column is NULL?", ["column = NULL", "column == NULL", "column IS NULL", "column HAS NULL"], 2, "Because NULL represents an unknown value, SQL uses IS NULL rather than equality to test for it.")
q("NULLs and Expressions", "Easy", "What does COALESCE(a, b, c) return?", ["The first non-NULL expression", "The last expression always", "The largest expression", "The number of NULL expressions"], 0, "COALESCE evaluates its arguments from left to right and returns the first non-NULL value.")
q("NULLs and Expressions", "Medium", "What is the result of NULL + 5 in ordinary SQL null semantics?", ["5", "NULL", "0", "An error in every database"], 1, "Arithmetic involving NULL normally produces NULL because the unknown value makes the result unknown.")
q("NULLs and Expressions", "Easy", "Which expression counts every row, including rows where a particular column is NULL?", ["COUNT(column_name)", "COUNT(NULL)", "COUNT(*)", "COUNT(EMPTY)"], 2, "COUNT(*) counts rows, while COUNT(column_name) counts only non-NULL values in that column.")
q("NULLs and Expressions", "Medium", "Which operator is the standard SQL concatenation operator in many implementations?", ["+", "||", "&", "JOIN"], 1, "The double-pipe operator is standard SQL string concatenation, although some products also provide CONCAT or use another operator.")
q("NULLs and Expressions", "Easy", "Which expression provides conditional logic inside a SQL statement?", ["CASE", "SWITCHROW", "IFTABLE", "CHOOSE TABLE"], 0, "CASE evaluates conditions and returns the result associated with the first matching branch.")
q("NULLs and Expressions", "Easy", "What is the purpose of CAST?", ["To filter rows", "To join tables", "To convert a value to a specified data type", "To create a database"], 2, "CAST explicitly converts an expression from one data type to another when the conversion is supported.")
q("NULLs and Expressions", "Medium", "What does NULLIF(a, b) return when a and b are equal?", ["a", "b", "0", "NULL"], 3, "NULLIF returns NULL when its two expressions compare equal; otherwise it returns the first expression.")
q("NULLs and Expressions", "Hard", "What is the purpose of IS NOT DISTINCT FROM where supported?", ["It treats two NULL values as equal for comparison", "It removes duplicates from a table", "It disables indexes", "It converts NULL to zero"], 0, "IS NOT DISTINCT FROM provides null-safe equality: two NULLs compare as equal, while NULL and a non-NULL do not.")

# Aggregate functions (41-50)
q("Aggregate Functions", "Easy", "What does COUNT(*) return?", ["The number of rows in the input", "The number of columns", "The sum of all numeric values", "The number of distinct tables"], 0, "COUNT(*) counts rows, including rows containing NULL values in individual columns.")
q("Aggregate Functions", "Easy", "What does COUNT(column_name) exclude?", ["Duplicate non-NULL values", "Rows where the column is NULL", "Rows where the column is zero", "Rows from joined tables"], 1, "COUNT of a column counts only non-NULL values, although duplicate values are counted separately unless DISTINCT is used.")
q("Aggregate Functions", "Easy", "Which aggregate calculates a total?", ["TOTALIZE", "ADD_ROWS", "SUM", "COMBINE"], 2, "SUM adds the non-NULL numeric values in its input.")
q("Aggregate Functions", "Easy", "How does AVG normally treat NULL input values?", ["It treats NULL as zero", "It ignores NULL values", "It returns NULL for every group", "It raises an error"], 1, "AVG ignores NULL inputs; the average is calculated over non-NULL values, unless no values remain.")
q("Aggregate Functions", "Easy", "What is the purpose of GROUP BY?", ["To combine tables physically", "To create an index", "To group rows for aggregate calculations", "To restrict users"], 2, "GROUP BY forms groups with equal grouping expressions so aggregates can be calculated per group.")
q("Aggregate Functions", "Easy", "What is the purpose of HAVING?", ["To filter groups after aggregation", "To filter individual rows before grouping", "To sort groups", "To define a primary key"], 0, "HAVING filters grouped results using aggregate or group-level conditions.")
q("Aggregate Functions", "Medium", "Why is an aggregate condition usually written in HAVING instead of WHERE?", ["WHERE cannot filter any rows", "The aggregate value is produced after row filtering and grouping", "HAVING cannot use expressions", "WHERE only works with strings"], 1, "WHERE operates on individual input rows before grouping, while HAVING can evaluate values produced for a group.")
q("Aggregate Functions", "Medium", "What does a query with an aggregate and no GROUP BY usually return?", ["One result row for the entire input", "One row per input row", "No rows", "One row per column"], 0, "Without GROUP BY, the aggregate treats the qualifying input as one group and normally returns one row.")
q("Aggregate Functions", "Easy", "What does MIN return?", ["The smallest value in its input", "The number of rows", "The first inserted row", "The median value"], 0, "MIN returns the minimum according to the data type's ordering rules.")
q("Aggregate Functions", "Medium", "Which logical sequence best describes filtering and grouping?", ["HAVING, GROUP BY, WHERE", "WHERE, GROUP BY, HAVING", "GROUP BY, WHERE, HAVING", "ORDER BY, WHERE, GROUP BY"], 1, "A query first filters input rows with WHERE, forms groups with GROUP BY, and then filters groups with HAVING.")

# Joins (51-60)
q("Joins", "Easy", "What does an INNER JOIN return?", ["Only rows with a matching row on both sides", "All rows from the left table", "All rows from both tables", "Only unmatched rows"], 0, "An inner join retains combinations for which the join condition is true in both inputs.")
q("Joins", "Easy", "What does a LEFT JOIN preserve?", ["All rows from the right table", "Only matching rows", "All rows from the left table", "Only rows with NULL keys"], 2, "A left outer join preserves every left-side row and fills right-side columns with NULL when no match exists.")
q("Joins", "Easy", "What does a RIGHT JOIN preserve?", ["All rows from the left table", "All rows from the right table", "Only duplicate rows", "Only unmatched rows"], 1, "A right outer join preserves every right-side row and supplies NULLs for missing left-side matches.")
q("Joins", "Medium", "What does a FULL OUTER JOIN include?", ["Only matching rows", "Only left-side rows", "Only right-side rows", "Matching and unmatched rows from both sides"], 3, "A full outer join returns matches plus unmatched rows from each input, using NULLs for the missing side.")
q("Joins", "Easy", "What is the result of a CROSS JOIN?", ["A Cartesian product of the two inputs", "Only equal primary keys", "The left table with NULLs", "An automatically indexed table"], 0, "A cross join combines every row from the first input with every row from the second input.")
q("Joins", "Easy", "What is a self join?", ["Joining a table to itself", "Joining only primary keys", "Joining two databases", "Joining without a condition"], 0, "A self join uses two aliases for the same table, often to compare related rows such as employees and managers.")
q("Joins", "Easy", "Which clause normally contains a join matching condition?", ["ON", "MATCH", "USING ONLY", "CONNECT"], 0, "The ON clause specifies the Boolean condition used to match rows in a join.")
q("Joins", "Medium", "What can happen if a join omits its intended matching condition?", ["The query always returns zero rows", "The database adds the condition automatically", "The query may produce a Cartesian product", "The query becomes a view"], 2, "Without the intended predicate, every combination may match, producing many more rows than expected.")
q("Joins", "Medium", "What does NATURAL JOIN use to match columns?", ["Columns with the same names", "Only columns named id", "The first column in each table", "Randomly selected columns"], 0, "NATURAL JOIN implicitly matches same-named columns, which can make it fragile when schemas change.")
q("Joins", "Medium", "Why can a one-to-many join return more rows than the left table?", ["SQL duplicates the database", "One left row can match multiple right rows", "Primary keys stop working", "NULLs are expanded"], 1, "A one-to-many relationship legitimately produces one result row for each matching child row.")

# Keys and constraints (61-70)
q("Keys and Constraints", "Easy", "Which properties are required of a primary key?", ["It may contain duplicates", "It must be unique and NOT NULL", "It must always be a string", "It can reference only views"], 1, "A primary key identifies each row uniquely and cannot contain NULL values.")
q("Keys and Constraints", "Easy", "What does a foreign key usually reference?", ["A primary key or candidate key in another table", "Only a view name", "A stored procedure", "A database user"], 0, "A foreign key enforces a relationship by referencing a key in the same or another table.")
q("Keys and Constraints", "Medium", "What is a candidate key?", ["Any nullable column", "A key used only for sorting", "A minimal set of columns that uniquely identifies a row", "A key generated only by a sequence"], 2, "A candidate key is a minimal unique identifier; one candidate key is chosen as the primary key.")
q("Keys and Constraints", "Easy", "What is a composite key?", ["A key made from multiple columns", "A key stored in a view", "A key with duplicate values", "A key made only from computed columns"], 0, "A composite key uses two or more columns together to identify a row.")
q("Keys and Constraints", "Easy", "What is the purpose of a UNIQUE constraint?", ["To prevent duplicate values for its constrained key", "To allow every value to be NULL", "To delete duplicates automatically", "To make a table read-only"], 0, "A UNIQUE constraint enforces uniqueness for the constrained column or column combination, subject to DBMS NULL rules.")
q("Keys and Constraints", "Easy", "What does a NOT NULL constraint prevent?", ["Duplicate values", "Negative values", "Missing NULL values in the column", "Foreign-key references"], 2, "NOT NULL requires every inserted or updated row to provide a value for that column.")
q("Keys and Constraints", "Easy", "What does a CHECK constraint do?", ["Validates that a row satisfies a condition", "Creates an automatic backup", "Joins two tables", "Encrypts data"], 0, "CHECK rejects inserts or updates that do not satisfy its Boolean condition.")
q("Keys and Constraints", "Easy", "When is a DEFAULT value used?", ["When a value is omitted during insert", "Whenever a query returns NULL", "When a table is dropped", "When a foreign key is invalid"], 0, "A DEFAULT supplies a value when an insert does not explicitly provide one for the column.")
q("Keys and Constraints", "Easy", "How many primary keys can a table have?", ["Exactly one constraint, possibly composite", "Unlimited primary keys", "One per column", "None if it has a foreign key"], 0, "A table has one primary-key constraint, although that key may contain multiple columns.")
q("Keys and Constraints", "Medium", "Can a foreign-key column be NULL?", ["Never", "Yes, if it is not declared NOT NULL", "Only in a view", "Only when its table has no primary key"], 1, "A nullable foreign key can represent an optional relationship; NULL does not require a matching referenced key.")

# Normalization (71-80)
q("Normalization", "Easy", "What is the main goal of first normal form (1NF)?", ["To allow repeating groups", "To make every value atomic", "To remove all indexes", "To require one table only"], 1, "1NF requires each field to hold an atomic value and removes repeating groups from the relational design.")
q("Normalization", "Medium", "What does second normal form (2NF) add to 1NF?", ["No partial dependency on part of a composite key", "No columns at all", "No foreign keys", "Every table must have two keys"], 0, "2NF removes partial dependencies, where a non-key attribute depends on only part of a composite candidate key.")
q("Normalization", "Medium", "What is the focus of third normal form (3NF)?", ["Removing transitive dependencies of non-key attributes", "Adding duplicate data", "Removing every primary key", "Storing all values as text"], 0, "3NF removes dependencies in which a non-key attribute depends on another non-key attribute.")
q("Normalization", "Hard", "What is the defining condition of BCNF?", ["Every determinant is a candidate key", "Every table must have a single column", "Every row must be duplicated", "Every foreign key must be nullable"], 0, "Boyce-Codd normal form requires every determinant in a non-trivial functional dependency to be a candidate key.")
q("Normalization", "Easy", "Why is normalization used?", ["To reduce unnecessary redundancy and update anomalies", "To make every query slower", "To remove all relationships", "To prevent indexing"], 0, "Normalization organizes dependent data to reduce duplication and anomalies during insert, update, and delete operations.")
q("Normalization", "Medium", "Why might a system deliberately denormalize data?", ["To reduce joins for read-heavy workloads", "To eliminate all constraints", "To make data impossible to query", "To avoid defining a schema"], 0, "Denormalization can duplicate selected data to improve read performance, at the cost of more storage and consistency work.")
q("Normalization", "Medium", "What is a partial dependency?", ["A non-key attribute depends on part of a composite key", "A table has no primary key", "A query uses only part of a column", "A foreign key references two tables"], 0, "A partial dependency occurs when a non-key attribute depends on only a proper subset of a composite key.")
q("Normalization", "Medium", "Which dependency is transitive?", ["A determines B and B determines C, so A determines C", "A determines itself only", "A and B are unrelated", "Every row has a unique value"], 0, "A transitive dependency passes through another attribute, such as student_id -> department_id -> department_name.")
q("Normalization", "Easy", "Which is an update anomaly?", ["Having to change the same fact in multiple rows", "Sorting rows in descending order", "Using a WHERE clause", "Creating a view"], 0, "Redundant storage can require the same fact to be updated in several places, risking inconsistent values.")
q("Normalization", "Hard", "What should a good lossless decomposition preserve?", ["The ability to reconstruct the original relation by joining decomposed tables", "Only the original row order", "Only duplicate rows", "No functional dependencies"], 0, "A lossless decomposition allows the original relation to be recovered without introducing spurious tuples.")

# Subqueries and CTEs (81-90)
q("Subqueries and CTEs", "Easy", "What is a subquery?", ["A query nested inside another SQL statement", "A database backup", "A type of index", "A table constraint"], 0, "A subquery is a nested SELECT used as a scalar value, set, table expression, or predicate input.")
q("Subqueries and CTEs", "Medium", "What makes a subquery correlated?", ["It references a column from the outer query", "It always returns a table", "It uses only aggregate functions", "It has no WHERE clause"], 0, "A correlated subquery is evaluated in relation to the current row of its outer query because it references outer columns.")
q("Subqueries and CTEs", "Easy", "What does EXISTS test?", ["Whether a subquery returns at least one row", "Whether a column is indexed", "Whether a value is numeric", "Whether a transaction committed"], 0, "EXISTS returns true when its subquery produces at least one row, without needing to return the row values.")
q("Subqueries and CTEs", "Medium", "What is required of a scalar subquery used as a value?", ["It must return at most one value", "It must return exactly one table", "It must contain GROUP BY", "It must use DISTINCT"], 0, "A scalar subquery is expected to produce one value; returning multiple rows generally causes an error.")
q("Subqueries and CTEs", "Easy", "What can an IN subquery provide?", ["A set of values for membership testing", "A transaction lock", "A new database user", "A table index"], 0, "The subquery result supplies values against which the outer expression is tested for membership.")
q("Subqueries and CTEs", "Easy", "Which keyword begins a common table expression?", ["WITH", "TEMP", "DEFINE", "COMMON"], 0, "WITH introduces one or more named query expressions that can be referenced by the statement that follows.")
q("Subqueries and CTEs", "Hard", "What is a recursive CTE useful for?", ["Hierarchies and graph-like repeated relationships", "Encrypting columns", "Creating indexes automatically", "Changing a database password"], 0, "A recursive CTE repeatedly applies a query to traverse structures such as org charts or category trees.")
q("Subqueries and CTEs", "Medium", "What is a derived table?", ["A subquery used in the FROM clause", "A table created by a trigger only", "A table with no columns", "A physical backup"], 0, "A derived table is a query result given an alias and used as a row source in the FROM clause.")
q("Subqueries and CTEs", "Medium", "What is an anti-join pattern commonly expressed with NOT EXISTS?", ["Find rows with no matching related row", "Find every duplicate row", "Sort by a foreign key", "Update all rows"], 0, "NOT EXISTS is commonly used to return rows for which no related row satisfies the correlated condition.")
q("Subqueries and CTEs", "Medium", "Where can a scalar subquery be used?", ["In an expression such as a SELECT-list or WHERE predicate", "Only in CREATE TABLE", "Only after ORDER BY", "Only in a GRANT statement"], 0, "A scalar subquery can provide one value wherever the SQL grammar accepts an expression.")

# Set operations and three-valued logic (91-100)
q("Set Operations", "Easy", "What does UNION do by default?", ["Combines results and removes duplicate rows", "Combines results and keeps every duplicate", "Joins columns by name", "Updates both source tables"], 0, "UNION combines compatible result sets and removes duplicate rows unless UNION ALL is used.")
q("Set Operations", "Easy", "What does UNION ALL do?", ["Combines results while preserving duplicates", "Removes all NULL values", "Joins tables by their primary keys", "Returns only common rows"], 0, "UNION ALL concatenates the result sets without duplicate elimination.")
q("Set Operations", "Easy", "What does INTERSECT return?", ["Rows common to both result sets", "Rows from the first result only", "All rows with duplicates", "Columns common to two tables"], 0, "INTERSECT returns the distinct rows that appear in both compatible result sets.")
q("Set Operations", "Easy", "What does EXCEPT return?", ["Rows in the first result that are not in the second", "Rows in both results", "All rows from the second result", "The Cartesian product"], 0, "EXCEPT performs set difference: it retains rows present in the first query but absent from the second.")
q("Set Operations", "Medium", "What must corresponding SELECT lists generally have for a set operation?", ["The same number of compatible columns", "The same table name", "Identical column aliases only", "A primary key in every column"], 0, "Set-operation inputs must align in column count and have data types that can be combined.")
q("Set Operations", "Medium", "What are the three logical truth values used by SQL null semantics?", ["TRUE, FALSE, and UNKNOWN", "TRUE, FALSE, and MAYBE-ERROR", "YES, NO, and NULL-ROW", "1, 2, and 3"], 0, "Comparisons involving NULL can evaluate to UNKNOWN, giving SQL three-valued logic.")
q("Set Operations", "Medium", "What happens to a WHERE predicate that evaluates to UNKNOWN?", ["The row is not selected", "The row is always selected", "It is treated as TRUE", "It deletes the row"], 0, "WHERE retains only rows for which the predicate is TRUE; FALSE and UNKNOWN are filtered out.")
q("Set Operations", "Hard", "Why can NOT IN behave unexpectedly when its list or subquery contains NULL?", ["The comparison can become UNKNOWN", "NULL is treated as every value", "NOT IN becomes a join", "NULL is converted to zero"], 0, "A NULL in the comparison set can make the negated equality unknown, so rows may not satisfy the predicate.")
q("Set Operations", "Medium", "What does IS TRUE explicitly test?", ["Whether an expression evaluates to TRUE", "Whether an expression is non-numeric", "Whether a table has rows", "Whether a value is unique"], 0, "IS TRUE is a null-safe truth test that is true only when the expression is TRUE.")
q("Set Operations", "Medium", "What is a practical way to compare a nullable value with a fallback?", ["Use COALESCE before applying the comparison", "Use DROP TABLE", "Use CROSS JOIN", "Use GRANT"], 0, "COALESCE can replace NULL with an agreed fallback before a comparison, when that semantics is appropriate.")

# Indexes and query plans (101-110)
q("Indexes and Query Plans", "Easy", "What is the main purpose of an index?", ["To speed up suitable data lookups", "To replace all constraints", "To store database backups", "To format query output"], 0, "An index provides an additional access path that can reduce the work needed to find matching rows.")
q("Indexes and Query Plans", "Medium", "Which index structure commonly supports equality and range searches?", ["B-tree", "Image map", "Circular queue", "Packet table"], 0, "B-tree family indexes are widely used for ordered equality and range access.")
q("Indexes and Query Plans", "Medium", "What is the leftmost-prefix idea for a composite index on (a, b, c)?", ["Searches starting with a can often use the index effectively", "Only c can use the index", "The index stores only a", "The order never matters"], 0, "Many B-tree optimizers can use the leading columns of a composite index for search and ordering.")
q("Indexes and Query Plans", "Hard", "What is a covering index?", ["An index containing all columns needed by a query", "An index that covers a table with a view", "An index that prevents all updates", "An index with no key"], 0, "A covering index can satisfy a query from the index alone, avoiding extra table or heap lookups.")
q("Indexes and Query Plans", "Easy", "What is a common cost of adding indexes?", ["They add storage and can slow inserts and updates", "They remove all query results", "They prevent SELECT", "They always increase table size tenfold"], 0, "Indexes need storage and must be maintained when indexed data changes.")
q("Indexes and Query Plans", "Medium", "Why might an index on a low-cardinality column be less useful?", ["A lookup may still match a large fraction of the table", "Low-cardinality columns cannot be indexed", "It changes the column type", "It drops duplicate rows"], 0, "If a value matches many rows, scanning the table or using another access path may be cheaper than index lookups.")
q("Indexes and Query Plans", "Easy", "What additional rule can a unique index enforce?", ["Uniqueness of its indexed key values", "Foreign-key cascading", "Transaction durability", "Column encryption"], 0, "A unique index rejects duplicate non-NULL key combinations according to the DBMS's NULL behavior.")
q("Indexes and Query Plans", "Medium", "What does a clustered index generally influence?", ["The physical or primary storage order of table rows", "The SQL language version", "The number of database users", "Whether NULL exists"], 0, "In systems that support the concept, a clustered index associates table storage with an index order.")
q("Indexes and Query Plans", "Hard", "Why can applying a function to an indexed column hurt index use?", ["The expression may not be searchable through the original index", "Functions always delete indexes", "Functions turn rows into tables", "The column becomes a foreign key"], 0, "A predicate such as function(column) may require transforming many values unless a matching expression index or rewrite is available.")
q("Indexes and Query Plans", "Easy", "What does EXPLAIN usually show?", ["The optimizer's planned execution strategy", "The database password", "Every historical transaction", "A table's data values only"], 0, "EXPLAIN exposes plan steps such as scans, joins, estimated rows, and access methods.")

# Views (111-120)
q("Views", "Easy", "What is a regular SQL view?", ["A named query presented as a virtual table", "A physical backup file", "An index on every column", "A stored password"], 0, "A view stores a query definition and presents its result as a table-like object; it usually does not store the result rows itself.")
q("Views", "Easy", "Which command creates a view?", ["CREATE VIEW", "MAKE VIRTUAL TABLE", "BUILD QUERY", "NEW VIEW ONLY"], 0, "CREATE VIEW defines a named view from a SELECT statement.")
q("Views", "Medium", "What can limit whether a view is updatable?", ["Joins, aggregates, and derived expressions in its definition", "The view name length only", "The number of database users", "Whether the base table has rows"], 0, "A DBMS may allow updates only when it can unambiguously map view rows back to base-table rows.")
q("Views", "Medium", "What does a materialized view store?", ["A persisted result of a query", "Only a table name", "A database user", "An encryption key"], 0, "A materialized view stores query results and must be refreshed when source data changes.")
q("Views", "Easy", "How can a view improve security?", ["It can expose selected columns or rows instead of the full base table", "It makes passwords unnecessary", "It disables all transactions", "It guarantees encryption"], 0, "Privileges can be granted on a view that reveals only the data a user needs.")
q("Views", "Medium", "What can happen when an underlying table is changed?", ["A dependent view may become invalid or require adjustment", "The view always changes into a table", "All users are deleted", "Indexes are automatically removed from every table"], 0, "A view depends on its referenced objects, so schema changes can invalidate or alter its behavior.")
q("Views", "Easy", "What does DROP VIEW remove?", ["The view definition", "The underlying base-table rows in every case", "All database schemas", "The database server"], 0, "DROP VIEW removes the view object; it does not normally delete data from its base tables.")
q("Views", "Medium", "Can a view be defined using multiple tables?", ["Yes, if its SELECT statement uses joins or other valid sources", "No, a view must always use one table", "Only if it is materialized", "Only with a trigger"], 0, "A view can be built from joins, subqueries, CTEs, and other query expressions allowed by the DBMS.")
q("Views", "Hard", "What does WITH CHECK OPTION enforce on an updatable view?", ["Changes through the view must continue to satisfy its view predicate", "Every row must have a primary key", "The view must be materialized", "The view cannot be selected"], 0, "WITH CHECK OPTION prevents an update or insert through the view from creating a row that the view would no longer show.")
q("Views", "Easy", "Does a normal non-materialized view usually store its own result rows?", ["No, it stores a query definition", "Yes, always", "Only when selected", "Only when it has a primary key"], 0, "A regular view is evaluated from its defining query when referenced, subject to optimizer behavior.")

# Transactions and ACID (121-130)
q("Transactions and ACID", "Easy", "What does atomicity mean?", ["A transaction is all-or-nothing", "Transactions never run concurrently", "Every value is numeric", "All queries use an index"], 0, "Atomicity ensures that a transaction's changes are either all applied or all rolled back.")
q("Transactions and ACID", "Easy", "What does consistency mean in ACID?", ["A committed transaction preserves database rules", "Every query returns the same rows", "All transactions use one table", "All values are duplicated"], 0, "Consistency means transactions move the database between valid states that satisfy defined constraints and invariants.")
q("Transactions and ACID", "Easy", "What does isolation address?", ["How concurrent transactions interact", "How tables are named", "How backups are compressed", "How SQL is formatted"], 0, "Isolation controls the visibility and interference of operations performed by concurrent transactions.")
q("Transactions and ACID", "Easy", "What does durability mean?", ["Committed changes survive a failure according to the system's guarantees", "Uncommitted changes are always saved", "Queries cannot be rolled back", "Indexes never change"], 0, "Durability protects committed results from being lost after a crash or restart within the database's guarantees.")
q("Transactions and ACID", "Easy", "What does ROLLBACK normally do?", ["Undoes uncommitted changes in the current transaction", "Deletes the database", "Commits every pending change", "Creates a table"], 0, "ROLLBACK aborts the transaction or rolls it back to a savepoint, depending on the command form.")
q("Transactions and ACID", "Medium", "What is a SAVEPOINT used for?", ["To mark a point for partial rollback", "To create a primary key", "To grant privileges", "To sort rows"], 0, "A savepoint lets a transaction undo work after that point without necessarily discarding all earlier work.")
q("Transactions and ACID", "Easy", "What is a common effect of autocommit mode?", ["Each completed statement is committed as its own transaction", "All statements are permanently rolled back", "Only SELECT statements run", "Every table becomes read-only"], 0, "In autocommit mode, each statement commonly forms and commits its own transaction unless explicitly grouped.")
q("Transactions and ACID", "Medium", "What is a dirty read?", ["Reading data written by another transaction before it commits", "Reading a row twice", "Reading an indexed column", "Reading a NULL"], 0, "A dirty read can observe changes that may later be rolled back by the writing transaction.")
q("Transactions and ACID", "Medium", "What is a lost update?", ["One committed update overwrites another concurrent update", "A row is never inserted", "A query loses its alias", "An index is rebuilt"], 0, "A lost update occurs when concurrent writes are not coordinated and one write replaces the effect of another.")
q("Transactions and ACID", "Easy", "Which commands usually mark transaction boundaries?", ["COMMIT and ROLLBACK", "SELECT and WHERE", "CREATE and GRANT", "JOIN and GROUP BY"], 0, "COMMIT completes a transaction and ROLLBACK aborts it or returns it to a savepoint.")

# Isolation levels and concurrency (131-140)
q("Isolation and Concurrency", "Medium", "Which standard isolation level permits the most visibility of uncommitted changes?", ["SERIALIZABLE", "REPEATABLE READ", "READ COMMITTED", "READ UNCOMMITTED"], 3, "READ UNCOMMITTED permits dirty reads and is the weakest standard isolation level.")
q("Isolation and Concurrency", "Easy", "What does READ COMMITTED normally prevent?", ["Dirty reads", "All deadlocks", "All phantom reads", "All write conflicts"], 0, "READ COMMITTED exposes only data committed before the read, though other anomalies may still occur.")
q("Isolation and Concurrency", "Medium", "What is the usual goal of REPEATABLE READ?", ["A row read twice remains stable within the transaction", "Every transaction runs alone", "All uncommitted data is visible", "It disables indexes"], 0, "REPEATABLE READ prevents a row already read from changing as observed during the transaction, with exact phantom behavior depending on the DBMS.")
q("Isolation and Concurrency", "Easy", "Which standard level provides the strongest isolation?", ["READ UNCOMMITTED", "READ COMMITTED", "REPEATABLE READ", "SERIALIZABLE"], 3, "SERIALIZABLE aims to produce behavior equivalent to serial execution of transactions.")
q("Isolation and Concurrency", "Medium", "What is a phantom read?", ["A repeated range query sees newly inserted or removed qualifying rows", "A query returns a NULL", "A primary key changes automatically", "A table disappears from a schema"], 0, "A phantom is a new or missing row that appears in a repeated predicate-based query due to concurrent changes.")
q("Isolation and Concurrency", "Hard", "What is the basic idea of MVCC?", ["Readers use row versions so reads can avoid some writer blocking", "Every table has one row", "Queries are converted to files", "All locks are removed"], 0, "Multi-version concurrency control maintains versions so transactions can read a consistent snapshot while writers make changes.")
q("Isolation and Concurrency", "Medium", "What is a non-repeatable read?", ["The same row returns different committed values when read twice", "A query returns no columns", "A row is read before insertion", "A table has no index"], 0, "A concurrent committed update can cause the same transaction to see different values for a previously read row.")
q("Isolation and Concurrency", "Easy", "What does a dirty read observe?", ["Uncommitted data", "Only data from a backup", "Only duplicate rows", "Data after a table is dropped"], 0, "Dirty reads see changes that the writing transaction has not committed and may still roll back.")
q("Isolation and Concurrency", "Medium", "What is a deadlock?", ["Transactions wait in a cycle for resources held by one another", "A transaction that has no rows", "A duplicate primary key", "An empty result set"], 0, "A deadlock occurs when transactions form a wait cycle, so a DBMS must detect, prevent, or resolve it.")
q("Isolation and Concurrency", "Medium", "What is one possible response to a lock wait exceeding its timeout?", ["Abort or fail the waiting operation", "Automatically grant every privilege", "Drop the locked table", "Convert all values to NULL"], 0, "A lock timeout commonly causes the waiting statement or transaction to fail so it can be retried or handled.")

# Locking and concurrency control (141-150)
q("Locking", "Easy", "What is a shared lock primarily used for?", ["Reading data while allowing compatible readers", "Deleting a table", "Granting a role", "Creating a database"], 0, "Shared locks protect data for reading and can generally coexist with other shared locks.")
q("Locking", "Easy", "What is an exclusive lock primarily used for?", ["Writing or changing data", "Sorting a result", "Reading metadata only", "Creating an alias"], 0, "An exclusive lock protects a resource for a writer and normally conflicts with other reads or writes that could interfere.")
q("Locking", "Medium", "What does two-phase locking generally require?", ["A growing phase for acquiring locks and a shrinking phase for releasing them", "Two databases for every query", "Two primary keys per table", "Two commits for every row"], 0, "Two-phase locking separates lock acquisition from lock release to help provide serializable behavior.")
q("Locking", "Medium", "Which is a common deadlock prevention technique?", ["Require transactions to acquire resources in a consistent order", "Disable every constraint", "Use SELECT * everywhere", "Add a random delay to every query"], 0, "A global resource order prevents cycles in the wait-for graph when transactions follow it.")
q("Locking", "Hard", "What is optimistic concurrency control?", ["Transactions proceed with limited blocking and check for conflicts before commit", "Every transaction takes a table lock first", "Only SELECT statements are allowed", "Rows are never validated"], 0, "Optimistic control assumes conflicts are uncommon and validates or detects them before accepting a write.")
q("Locking", "Medium", "What is a benefit of row-level locking over table-level locking?", ["More unrelated transactions can proceed concurrently", "It always uses less memory", "It removes all deadlocks", "It prevents indexes"], 0, "Row-level locks protect smaller resources, which can improve concurrency when transactions touch different rows.")
q("Locking", "Easy", "What is a likely tradeoff of table-level locking?", ["It can reduce concurrency because a larger resource is locked", "It cannot protect data", "It always prevents reads", "It only works for views"], 0, "Locking an entire table can block otherwise independent operations, though it may have lower lock-management overhead.")
q("Locking", "Medium", "What is a cascading rollback?", ["Rolling back a transaction also forces dependent uncommitted work to roll back", "Rolling back only a SELECT alias", "Restoring an index", "Deleting all committed rows"], 0, "If one transaction used uncommitted data from another, aborting the source can require dependent work to be undone.")
q("Locking", "Medium", "What is SELECT FOR UPDATE commonly intended to do?", ["Lock selected rows for a subsequent update", "Create a view", "Sort rows permanently", "Grant update privilege"], 0, "In systems that support it, SELECT FOR UPDATE locks selected rows so the transaction can safely update them.")
q("Locking", "Medium", "How can MVCC often improve read/write concurrency?", ["Readers can use versions instead of waiting for every writer", "It removes the need for commits", "It turns every query into a cross join", "It makes every write read-only"], 0, "MVCC can let readers use a consistent version while writers create newer versions, reducing blocking in many workloads.")

# Window functions (151-160)
q("Window Functions", "Easy", "What is a key property of a window function?", ["It calculates across related rows while preserving the individual result rows", "It always collapses rows into one row", "It creates a new table", "It can only be used in INSERT"], 0, "Window functions compute values over a window of rows without grouping the result into one row per group.")
q("Window Functions", "Easy", "Which clause defines a window specification?", ["OVER", "WINDOWS ONLY", "RANGE BY", "ANALYZE"], 0, "OVER defines the partition, ordering, and optional frame used by a window function.")
q("Window Functions", "Easy", "What does ROW_NUMBER() assign?", ["A sequential number to rows in each window", "The number of columns", "The number of NULLs only", "A permanent primary key"], 0, "ROW_NUMBER assigns unique sequential numbers according to the window ordering, restarting for each partition.")
q("Window Functions", "Medium", "How does RANK handle ties?", ["Tied rows share a rank and later ranks can have gaps", "Every row gets a unique rank", "Ties are deleted", "It always returns only rank one"], 0, "RANK gives equal values the same rank and skips subsequent rank numbers based on the size of the tie.")
q("Window Functions", "Medium", "How does DENSE_RANK handle ties?", ["Tied rows share a rank and later ranks have no gaps", "Every row gets a different rank", "It ignores the ORDER BY", "It groups only NULL rows"], 0, "DENSE_RANK assigns the same rank to ties and increments by one for the next distinct value.")
q("Window Functions", "Easy", "What does PARTITION BY do inside OVER?", ["Divides rows into independent windows", "Physically partitions a database", "Deletes duplicate partitions", "Creates a table partition permanently"], 0, "PARTITION BY resets the window calculation for each group of equal partition expressions.")
q("Window Functions", "Easy", "What does ORDER BY do inside a window specification?", ["Defines the sequence used by the window calculation", "Sorts the stored table permanently", "Changes the primary key", "Filters rows before the query starts"], 0, "Window ORDER BY determines row sequence for ranking, offsets, and ordered aggregates.")
q("Window Functions", "Medium", "Which expression is suitable for a running total?", ["SUM(amount) OVER (ORDER BY event_time)", "COUNT(*) WHERE amount", "TOTAL ROWS BY amount", "SUM(amount) GROUP ONLY"], 0, "An ordered SUM window accumulates values through the sequence, subject to the DBMS default or specified frame.")
q("Window Functions", "Easy", "What does LAG commonly return?", ["A value from a preceding row", "The largest value", "The next table", "A count of groups"], 0, "LAG accesses a value from an earlier row in the window ordering.")
q("Window Functions", "Easy", "What does LEAD commonly return?", ["A value from a following row", "The previous transaction", "The first table column", "The number of indexes"], 0, "LEAD accesses a value from a later row in the window ordering.")

# Advanced window functions (161-170)
q("Advanced Window Functions", "Medium", "What does FIRST_VALUE return?", ["The first value in the window frame according to its ordering", "The first table created", "The smallest row count", "The first column in the schema"], 0, "FIRST_VALUE returns the value from the first row of the specified window frame.")
q("Advanced Window Functions", "Easy", "What does NTILE(4) generally do?", ["Divides ordered rows into four numbered buckets", "Returns the fourth row only", "Creates four tables", "Counts four NULLs"], 0, "NTILE distributes ordered rows as evenly as possible among the requested number of buckets.")
q("Advanced Window Functions", "Medium", "What does a frame such as ROWS BETWEEN 2 PRECEDING AND CURRENT ROW describe?", ["A moving three-row frame including the current row", "A three-table join", "Three previous transactions only", "A table constraint"], 0, "The frame includes the two preceding rows and the current row for the window calculation.")
q("Advanced Window Functions", "Hard", "What is a common way to select the top three salaries per department?", ["Use ROW_NUMBER or RANK with PARTITION BY department and filter the result", "Use DROP TABLE", "Use COUNT without a department", "Use CROSS JOIN only"], 0, "Ranking within each department and filtering the rank produces a top-N-per-group result.")
q("Advanced Window Functions", "Medium", "How does PARTITION BY department affect a ranking function?", ["The rank restarts for each department", "It merges all departments", "It deletes department values", "It sorts departments permanently"], 0, "Each partition is ranked independently, so the first row of every department can receive rank one.")
q("Advanced Window Functions", "Medium", "Which ranking function includes ties when selecting a top-N threshold?", ["RANK", "ROW_NUMBER", "COUNT", "LAG"], 0, "RANK assigns the same rank to ties, so filtering rank <= N can include all tied rows at the boundary.")
q("Advanced Window Functions", "Medium", "What can COUNT(*) OVER (PARTITION BY department) provide?", ["The department size on every row without collapsing the rows", "Only one department row", "A permanent department count column", "A count of tables"], 0, "The window count repeats each partition's row count alongside each original row.")
q("Advanced Window Functions", "Medium", "What is the typical range of PERCENT_RANK for a nonempty ordered partition?", ["0 to 1", "1 to 100 only", "-1 to 0", "The number of rows to infinity"], 0, "PERCENT_RANK is commonly calculated as (rank - 1) divided by (rows - 1), giving values from 0 to 1 when defined.")
q("Advanced Window Functions", "Hard", "Why is a window function often wrapped in a subquery before filtering on its result?", ["Window functions are generally evaluated after WHERE", "Subqueries are required for every SELECT", "Window functions cannot use ORDER BY", "Filtering always deletes windows"], 0, "A query layer is used because a SELECT-list window result is not normally available to the same query block's WHERE clause.")
q("Advanced Window Functions", "Medium", "What does a named WINDOW clause help provide?", ["A reusable window specification", "A database backup", "A new isolation level", "A foreign key"], 0, "A named window can reduce repetition when several window functions share partitioning or ordering rules.")

# Procedures, functions, and triggers (171-180)
q("Procedures and Triggers", "Easy", "What is a stored procedure?", ["A named program stored and executed by the database", "A physical index", "A table row", "A network protocol"], 0, "A stored procedure is a database object containing executable SQL and procedural logic, subject to DBMS support.")
q("Procedures and Triggers", "Easy", "What is a stored function generally expected to do?", ["Return a value", "Drop its database", "Disable every constraint", "Always start a transaction"], 0, "A stored function computes and returns a value and can often be used in expressions, subject to DBMS rules.")
q("Procedures and Triggers", "Easy", "What is a trigger?", ["Code that runs automatically in response to a database event", "A manual SELECT shortcut", "A type of index", "A table alias"], 0, "A trigger fires automatically for events such as insert, update, or delete when its condition and timing apply.")
q("Procedures and Triggers", "Easy", "When does a BEFORE trigger run?", ["Before the triggering row operation completes", "Only after a backup", "After the database shuts down", "Before a user logs in"], 0, "A BEFORE trigger runs before the triggering operation is applied, allowing validation or supported value adjustments.")
q("Procedures and Triggers", "Easy", "When does an AFTER trigger run?", ["After the triggering operation has occurred", "Before the SQL parser starts", "Only when no row matches", "Before a table exists"], 0, "An AFTER trigger runs after the associated operation, commonly for auditing or related actions.")
q("Procedures and Triggers", "Easy", "Can a stored procedure accept parameters?", ["Yes, if supported by the DBMS", "No, never", "Only through a view", "Only when it has no SQL"], 0, "Procedures commonly define input, output, or input-output parameters.")
q("Procedures and Triggers", "Medium", "What is the distinction between row-level and statement-level triggers?", ["Row-level fires per affected row; statement-level fires once per statement", "Row-level runs only on SELECT", "Statement-level cannot modify data", "They are identical in every DBMS"], 0, "The trigger granularity determines whether one firing occurs for each affected row or once for the triggering statement.")
q("Procedures and Triggers", "Medium", "Why should trigger chains be designed carefully?", ["They can create unexpected recursion or hidden side effects", "They make SELECT impossible", "They always remove indexes", "They disable NULL"], 0, "Triggers execute implicitly, so chained actions can create recursion, ordering surprises, or difficult-to-debug changes.")
q("Procedures and Triggers", "Easy", "Which statement commonly invokes a stored procedure?", ["CALL", "RUN TABLE", "EXECUTE ROW ONLY", "OPEN PROCEDURE"], 0, "CALL is standard-style syntax for invoking a stored procedure, though some products also use EXEC.")
q("Procedures and Triggers", "Hard", "Why can using a stored function in a SELECT have restrictions?", ["It may have side effects or affect optimization and determinism", "SELECT cannot return values", "Functions cannot read data", "Functions always create tables"], 0, "DBMSs can restrict side effects in query expressions to preserve predictable query behavior and optimization.")

# SQL security (181-190)
q("SQL Security", "Easy", "What vulnerability can result from concatenating untrusted input into SQL text?", ["SQL injection", "Buffer underflow", "ARP spoofing", "Disk fragmentation"], 0, "SQL injection occurs when attacker-controlled input changes the intended SQL command structure.")
q("SQL Security", "Easy", "What is the strongest general defense against SQL injection in application queries?", ["Parameterized queries or prepared statements", "String concatenation", "Removing all indexes", "Using SELECT *"], 0, "Parameters keep input values separate from SQL code, preventing them from being parsed as query syntax.")
q("SQL Security", "Easy", "What does the principle of least privilege recommend?", ["Grant only the permissions a user or service needs", "Give every user administrator access", "Avoid all authentication", "Use one shared password"], 0, "Least privilege limits the impact of mistakes or compromise by minimizing unnecessary access.")
q("SQL Security", "Easy", "Which command is used to assign object privileges?", ["GRANT", "ASSIGN ACCESS", "ALLOW TABLE", "OPEN ROLE"], 0, "GRANT assigns privileges such as SELECT, INSERT, UPDATE, or EXECUTE to users and roles.")
q("SQL Security", "Easy", "Which command removes assigned object privileges?", ["REVOKE", "UNGRANT", "DENY TABLE", "REMOVE ROLE DATA"], 0, "REVOKE removes previously granted permissions from a principal.")
q("SQL Security", "Medium", "How should application passwords generally be stored?", ["Using a slow, salted password-hashing scheme outside plain text", "As plain text in a table", "As reversible URL encoding", "In a public view"], 0, "Passwords should be protected with an appropriate salted password hash and never stored as plain text.")
q("SQL Security", "Easy", "How can a view support least privilege?", ["By exposing only approved rows or columns", "By granting every privilege", "By disabling authentication", "By storing passwords"], 0, "A view can present a limited projection or filter and be used as the object on which access is granted.")
q("SQL Security", "Easy", "What is a database role?", ["A named collection of privileges that can be granted to users", "A row lock", "A data type", "A backup file"], 0, "Roles simplify privilege management by grouping permissions for assignment to principals.")
q("SQL Security", "Medium", "Why are prepared statements safer than escaping input manually?", ["They separate SQL structure from parameter values", "They automatically encrypt the database", "They remove all constraints", "They force every query to use a view"], 0, "Prepared statements send query structure and values separately, avoiding many parsing ambiguities that manual escaping can miss.")
q("SQL Security", "Easy", "What is the purpose of database audit logging?", ["To record selected access or change events for review", "To make all queries faster", "To replace transactions", "To remove foreign keys"], 0, "Audit logs help investigate activity, compliance events, and unexpected data changes.")

# Data types and identifiers (191-200)
q("Data Types", "Easy", "What is the usual difference between CHAR and VARCHAR?", ["CHAR is fixed-length; VARCHAR is variable-length", "CHAR is numeric; VARCHAR is a date", "VARCHAR cannot store text", "They are always identical"], 0, "CHAR reserves a fixed-size character field, while VARCHAR stores a variable-length string up to its declared limit.")
q("Data Types", "Easy", "Which type is intended for exact decimal arithmetic?", ["DECIMAL or NUMERIC", "FLOAT only", "BLOB", "BOOLEAN"], 0, "DECIMAL and NUMERIC represent fixed-precision decimal values and are appropriate for exact amounts such as currency.")
q("Data Types", "Medium", "What is a common characteristic of FLOAT?", ["It represents approximate numeric values", "It always stores exact currency", "It stores binary files only", "It can hold only whole numbers"], 0, "Floating-point types use approximate representation and may introduce rounding differences.")
q("Data Types", "Easy", "What does the DATE type generally represent?", ["A calendar date", "Only a time zone", "A binary document", "A table relationship"], 0, "DATE represents a calendar date; whether it includes a time portion is determined by the DBMS type definition.")
q("Data Types", "Easy", "What does TIMESTAMP generally represent?", ["A date and time value", "A primary key only", "A boolean flag", "A table name"], 0, "TIMESTAMP stores a temporal date-time value, with time-zone behavior depending on the DBMS and variant.")
q("Data Types", "Easy", "What is the purpose of a BOOLEAN type where supported?", ["To represent true or false values", "To store arbitrary files", "To store dates only", "To create joins"], 0, "BOOLEAN represents logical truth values, although SQL products differ in their exact support and storage.")
q("Data Types", "Easy", "What is a BLOB designed to store?", ["Large binary data", "Only integers", "A foreign-key rule", "A query plan"], 0, "A BLOB stores binary large objects such as images or other opaque binary content.")
q("Data Types", "Medium", "What is a surrogate key?", ["An artificial identifier with no direct business meaning", "A duplicated natural description", "A foreign-key error", "A view definition"], 0, "A surrogate key is generated for identification, often as an integer or UUID, rather than derived from business attributes.")
q("Data Types", "Easy", "What can an identity column or sequence provide?", ["Automatically generated numeric or ordered key values", "Automatic encryption of all rows", "A replacement for every foreign key", "Only string formatting"], 0, "Identity columns and sequences generate values useful for surrogate keys and other numbering needs.")
q("Data Types", "Medium", "Why should identifiers and data types be chosen deliberately?", ["They affect validation, storage, comparison, and query behavior", "They only change column color", "They have no effect after CREATE TABLE", "They eliminate the need for constraints"], 0, "Type choices influence correctness, precision, storage, indexing, and how expressions compare values.")

# String and date functions (201-210)
q("String and Date Functions", "Easy", "What does UPPER(text) generally return?", ["The text converted to uppercase", "The text length", "The first word only", "A numeric hash"], 0, "UPPER converts alphabetic characters to uppercase according to the database's collation and character rules.")
q("String and Date Functions", "Easy", "What does LOWER(text) generally return?", ["The text converted to lowercase", "The text truncated to one character", "A date", "The number of words"], 0, "LOWER converts alphabetic characters to lowercase according to the database's character rules.")
q("String and Date Functions", "Easy", "What does LENGTH commonly return?", ["The length of a string", "The number of tables", "The largest numeric value", "The current date"], 0, "LENGTH returns a string length, though exact character-versus-byte semantics vary by DBMS and function name.")
q("String and Date Functions", "Easy", "What does TRIM commonly remove?", ["Leading or trailing whitespace", "All duplicate rows", "Foreign keys", "Indexes"], 0, "TRIM removes leading and trailing spaces or specified characters from a string.")
q("String and Date Functions", "Easy", "What does SUBSTRING do?", ["Extracts part of a string", "Groups table rows", "Creates a sequence", "Commits a transaction"], 0, "SUBSTRING returns a portion of a string using a start position and usually a length.")
q("String and Date Functions", "Easy", "What does CURRENT_DATE provide?", ["The current calendar date", "The current table name", "The current row count", "The previous transaction"], 0, "CURRENT_DATE is a standard-style expression for the current date at the time of evaluation.")
q("String and Date Functions", "Medium", "Why is storing dates in a date type preferable to storing them as arbitrary strings?", ["The database can validate and compare them using temporal semantics", "Strings always use less storage", "Dates cannot be indexed", "Strings automatically handle time zones"], 0, "Date types support meaningful ordering, validation, date arithmetic, and date-aware functions.")
q("String and Date Functions", "Medium", "What does EXTRACT(YEAR FROM some_date) return?", ["The year component", "The month name only", "The time zone only", "The number of days in the table"], 0, "EXTRACT retrieves a requested temporal field such as YEAR, MONTH, or DAY.")
q("String and Date Functions", "Easy", "Which expression can provide a display fallback when a name is NULL?", ["COALESCE(name, 'Unknown')", "DROP NULL name", "COUNT(name, 'Unknown')", "GROUP NULL name"], 0, "COALESCE returns the name when present and the fallback string when name is NULL.")
q("String and Date Functions", "Easy", "What does ROUND(number, 2) generally do?", ["Rounds the number to two decimal places", "Returns the second row", "Creates two indexes", "Converts the number to a date"], 0, "ROUND applies numeric rounding at the requested scale, subject to the DBMS's rounding rules.")

# Query optimization (211-220)
q("Query Optimization", "Easy", "Why should a query select only the columns it needs?", ["It can reduce data transfer and work", "It guarantees an index", "It prevents all joins", "It changes rows into columns"], 0, "Selecting only required columns can reduce I/O, network traffic, memory use, and the need to access wide rows.")
q("Query Optimization", "Medium", "Why can LIKE '%abc' be difficult to optimize with a normal B-tree index?", ["The leading wildcard prevents a useful known starting prefix", "LIKE cannot compare strings", "It always deletes the index", "The pattern matches only NULL"], 0, "A leading wildcard means the engine may need to inspect many values because the search has no fixed left prefix.")
q("Query Optimization", "Medium", "What are database statistics used for?", ["To estimate data distributions and choose query plans", "To store user passwords", "To define foreign keys", "To replace table data"], 0, "Optimizers use statistics about cardinality and distributions to estimate costs for scans, joins, and indexes.")
q("Query Optimization", "Hard", "What is a sargable predicate?", ["A predicate that can use an index or search argument efficiently", "A predicate that always returns NULL", "A trigger condition only", "A query with no WHERE clause"], 0, "Sargable predicates expose a searchable column expression in a form that can be used by an access method.")
q("Query Optimization", "Easy", "When might a full table scan be reasonable?", ["When a query needs a large fraction of the table", "Only when the table is empty", "Never", "Only when a primary key is missing"], 0, "For large result fractions, sequentially reading the table can cost less than many random index lookups.")
q("Query Optimization", "Medium", "Why can a query with many OR branches be harder to optimize?", ["The optimizer may need to combine multiple access paths or choose a scan", "OR is not allowed in SQL", "OR automatically drops indexes", "OR changes every value to NULL"], 0, "Disjunctive predicates can have complex selectivity and may require multiple index probes or a broader scan.")
q("Query Optimization", "Medium", "Why can large OFFSET values make pagination slower?", ["The database may still scan or discard many preceding rows", "OFFSET deletes the result", "OFFSET disables all SQL", "OFFSET always uses a table lock"], 0, "Offset pagination often requires finding and skipping earlier rows before returning the requested page.")
q("Query Optimization", "Medium", "What is keyset pagination?", ["Using the last seen key as a cursor for the next page", "Sorting by every column", "Using a random offset", "Returning every row at once"], 0, "Keyset pagination uses a stable ordered key and a predicate such as key > last_key to seek efficiently.")
q("Query Optimization", "Easy", "What is the N+1 query problem?", ["One query loads a list and an additional query runs for each item", "A query has exactly N columns", "A table has N+1 keys", "A transaction commits N times"], 0, "N+1 causes excessive round trips and can often be reduced with joins, batching, or eager loading.")
