q("Query Reasoning", "Easy", "What does COUNT(DISTINCT customer_id) measure?", ["The number of unique non-NULL customer IDs", "The number of orders including duplicates", "The largest customer ID", "The number of tables"], 0, "DISTINCT removes repeated customer IDs before COUNT counts them; NULL is not counted by COUNT of the expression.")
q("Query Reasoning", "Easy", "What does MAX(salary) return in a qualifying group?", ["The highest non-NULL salary value", "Every salary sorted", "The average salary", "The number of salaries"], 0, "MAX returns the greatest non-NULL value according to the type's ordering.")
