# Rotate answer choices using a deterministic pattern so the correct choice is
# not predictable from its position. The stored answer index is updated with it.
for index, item in enumerate(questions, start=1):
    shift = (index * 3 + index // 4) % 4
    item["options"] = item["options"][shift:] + item["options"][:shift]
    item["answer"] = (item["answer"] - shift) % 4

assert len(questions) == 250, f"Expected 250 questions, got {len(questions)}"
assert all(len(item["options"]) == 4 for item in questions)
assert all(0 <= item["answer"] < len(item["options"]) for item in questions)

Path(__file__).with_name("questionBank.json").write_text(json.dumps(questions, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
print(f"Wrote {len(questions)} SQL questions")
